91	  ): Promise<ToolInfoConfirmationDetails | false> {
92	    const decision = await this.getMessageBusDecision(abortSignal);
93	    if (decision === 'allow') {
94	      return false;
95	    }
96	
97	    if (decision === 'deny') {
98	      throw new Error(
99	        `Tool execution for "${
100	          this._toolDisplayName || this._toolName
101	        }" denied by policy.`,
102	      );
103	    }
104	
105	    // ask_user
106	    return {
107	      type: 'info',
108	      title: 'Enter Plan Mode',
109	      prompt:
110	        'This will restrict the agent to read-only tools to allow for safe planning.',
111	      onConfirm: async (outcome: ToolConfirmationOutcome) => {
