119	    if (this.confirmationOutcome === ToolConfirmationOutcome.Cancel) {
120	      return {
121	        llmContent: 'User cancelled entering Plan Mode.',
122	        returnDisplay: 'Cancelled',
123	      };
124	    }
125	
126	    this.config.setApprovalMode(ApprovalMode.PLAN);
127	
128	    // Ensure plans directory exists so that the agent can write the plan file.
129	    // In sandboxed environments, the plans directory must exist on the host
130	    // before it can be bound/allowed in the sandbox.
131	    const plansDir = this.config.storage.getPlansDir();
132	    if (!fs.existsSync(plansDir)) {
133	      try {
134	        fs.mkdirSync(plansDir, { recursive: true });
135	      } catch (e) {
136	        // Log error but don't fail; write_file will try again later
137	        debugLogger.error(`Failed to create plans directory: ${plansDir}`, e);
138	      }
139	    }
140	
141	    return {
142	      llmContent: 'Switching to Plan mode.',
143	      returnDisplay: this.params.reason
144	        ? `Switching to Plan mode: ${this.params.reason}`
145	        : 'Switching to Plan mode',
146	    };
147	  }
148	}
