}", "newString": "/**
 * Validates a plan file path for safety (traversal) and existence.
 *
 * Plan file references are interpreted relative to the plans directory, which
 * keeps them portable across machines and independent of the project root's
 * absolute location. Nested subdirectories within the plans directory are
 * supported. Absolute paths are honored as-is so callers may pass a
 * fully-resolved location.
 *
 * @param planPath The untrusted path to the plan file, relative to plansDir.
 * @param plansDir The authorized project plans directory (absolute).
 * @param projectRoot The absolute path to the project root directory.
 * @returns An error message if validation fails, or null if successful.
 */
export async function validatePlanPath(
  planPath: string,
  plansDir: string,
  projectRoot: string,
): Promise<string | null> {
  const resolvedPath = path.isAbsolute(planPath)
    ? planPath
    : path.join(plansDir, planPath);
  const realPath = resolveToRealPath(resolvedPath);
  const realPlansDir = resolveToRealPath(plansDir);

  // Guard against traversal escaping the plans directory, including via
  // symbolic links whose real target lives outside plansDir.
  if (!isSubpath(realPlansDir, realPath)) {
    return PlanErrorMessages.PATH_ACCESS_DENIED(planPath, plansDir);
  }

  if (!(await fileExists(resolvedPath))) {
    return PlanErrorMessages.FILE_NOT_FOUND(planPath);
  }

  return null;
